import {trigrams,hexagrams,bits,byBits} from './data.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const state={hex:hexagrams[10],view:'pair',running:!matchMedia('(prefers-reduced-motion: reduce)').matches,yaw:0.1,pitch:-.17,zoom:1,time:0};
const colors=['#8ab9ff','#a7dacf'];
const changeBit=(h,i)=>byBits([...bits(h)].map((v,j)=>i===j?(v==='1'?'0':'1'):v).join(''));
const neighbors=h=>Array.from({length:6},(_,i)=>changeBit(h,i));
function select(h,announce=true){state.hex=h;render();if(announce)$('#status').text=`第${h.id}卦，${h.name}。${h.meaning}：${h.story}`;}
function render(){const h=state.hex, nbs=neighbors(h);$('#stage-index').textContent=String(h.id).padStart(2,'0')+' / 64';$('#hex-number').textContent=String(h.id).padStart(2,'0');$('#hex-code').textContent=bits(h);$('#hex-name').textContent=h.name;$('#hex-nature').textContent=h.up.nature+h.low.nature;$('#meaning').textContent=h.meaning;$('#story').textContent=h.story+'。';$('#lower-label').textContent=`${h.low.id} ${h.low.symbol}　${h.low.geo}`;$('#upper-label').textContent=`${h.up.id} ${h.up.symbol}　${h.up.geo}`;
$('#yao').replaceChildren();for(let i=5;i>=0;i--){const b=document.createElement('button');b.type='button';b.setAttribute('aria-label',`${['初','二','三','四','五','上'][i]}爻，${bits(h)[i]==='1'?'阳':'阴'}爻，点击变为${nbs[i].name}卦`);b.innerHTML=`<span class="level">${['初','二','三','四','五','上'][i]}</span><span class="bars"><i></i>${bits(h)[i]==='0'?'<i></i>':''}</span><span class="destination">${nbs[i].name} ↗</span>`;b.onclick=()=>select(nbs[i]);$('#yao').append(b);}
$$('.cell').forEach(b=>{const id=Number(b.dataset.id);b.classList.toggle('active',id===h.id);b.classList.toggle('neighbor',nbs.some(n=>n.id===id));b.setAttribute('aria-pressed',String(id===h.id));});
$$('.geo-card').forEach(b=>b.classList.toggle('selected',h.low.id===b.dataset.id||h.up.id===b.dataset.id));
for(const [selector,t,label] of [['#lower-fact',h.low,'下卦'],['#upper-fact',h.up,'上卦']])$(selector).innerHTML=`<h3>${label} · ${t.id}　${t.geo}</h3><p>${t.fact}</p><p>${t.image}</p><p class="rep">代表流形<br>${t.rep}</p>`;
$('#scene').setAttribute('aria-label',`${h.name}卦空间意象：下卦${h.low.id}，${h.low.name}；上卦${h.up.id}，${h.up.name}。${h.story}`);draw();}
const matrix=$('#matrix');matrix.innerHTML='<div class="corner">上／下</div>';for(const t of trigrams){const d=document.createElement('div');d.className='axis';d.innerHTML=`<span class="symbol">${t.symbol}</span><span>${t.id}</span>`;matrix.append(d);}for(const up of trigrams){const d=document.createElement('div');d.className='axis row-axis';d.innerHTML=`<span class="symbol">${up.symbol}</span><span>${up.id}</span>`;matrix.append(d);for(const low of trigrams){const h=hexagrams.find(h=>h.up===up&&h.low===low);const b=document.createElement('button');b.className='cell';b.dataset.id=h.id;b.setAttribute('aria-label',`第${h.id}卦 ${h.name}，上${up.id}下${low.id}，${h.meaning}`);b.innerHTML=`<span class="num">${String(h.id).padStart(2,'0')}</span><span class="cell-name">${h.name}</span>`;b.onclick=()=>select(h);matrix.append(b);}}
for(const t of trigrams){const b=document.createElement('button');b.className='geo-card';b.dataset.id=t.id;b.setAttribute('aria-label',`${t.id}，${t.name}，查看纯卦`);b.innerHTML=`<canvas aria-hidden="true"></canvas><strong>${t.symbol} ${t.id} · ${t.geo}</strong><small>${t.word}</small>`;b.onclick=()=>{select(hexagrams.find(h=>h.low===t&&h.up===t));setView('pair');};$('#atlas-grid').append(b);}
function setView(v){state.view=v;$$('[data-view]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.view===v)));for(const name of ['pair','atlas','network'])$('#'+name+'-view').hidden=name!==v;draw();}
$$('[data-view]').forEach((b,i,all)=>{b.onclick=()=>setView(b.dataset.view);b.onkeydown=e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();const next=all[(i+(e.key==='ArrowRight'?1:all.length-1))%all.length];next.focus();setView(next.dataset.view);}};});
$('#swap').onclick=()=>select(byBits(state.hex.up.code+state.hex.low.code));$('#complement').onclick=()=>select(byBits([...bits(state.hex)].map(v=>v==='1'?'0':'1').join('')));$('#reverse').onclick=()=>select(byBits([...bits(state.hex)].reverse().join('')));
function motionText(){$('#motion').textContent=state.running?'暂停旋转':'继续旋转';$('#motion').setAttribute('aria-pressed',String(state.running));}$('#motion').onclick=()=>{state.running=!state.running;motionText();};motionText();$('#zoom').oninput=e=>{state.zoom=Number(e.target.value)/100;draw();};
$('#present').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else if(document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();else{$('#present').textContent='此浏览器不支持全屏';setTimeout(()=>$('#present').innerHTML='全屏展示 <span>⛶</span>',2400);}}catch{$('#status').textContent='当前浏览器无法进入全屏，仍可正常浏览。';}};document.addEventListener('fullscreenchange',()=>{$('#present').innerHTML=document.fullscreenElement?'退出全屏 <span>⛶</span>':'全屏展示 <span>⛶</span>';draw();});
const TAU=Math.PI*2;const line=(f,a,b,n=40)=>Array.from({length:n+1},(_,i)=>f(a+(b-a)*i/n));const modelCache={};
function model(kind){if(modelCache[kind])return modelCache[kind];const a=[];
const sphere=(cy=0,r=1)=>{for(let j=1;j<12;j++){const v=-Math.PI/2+j*Math.PI/12;a.push(line(u=>[r*Math.cos(v)*Math.cos(u),cy+r*Math.sin(v),r*Math.cos(v)*Math.sin(u)],0,TAU,56));}for(let j=0;j<14;j++){const u=j*TAU/14;a.push(line(v=>[r*Math.cos(v)*Math.cos(u),cy+r*Math.sin(v),r*Math.cos(v)*Math.sin(u)],-Math.PI/2,Math.PI/2,36));}};
if(kind==='sphere')sphere();
if(kind==='shell'){sphere(-.48,.53);sphere(.48,.53);for(let j=0;j<12;j++){let u=j*TAU/12;a.push(line(y=>[.53*Math.cos(u),y,.53*Math.sin(u)],-.48,.48,14));}}
if(kind==='grid'){for(let j=0;j<=6;j++)for(let k=0;k<=6;k++){let u=-.8+j*1.6/6,v=-.8+k*1.6/6;a.push([[-.8,u,v],[.8,u,v]],[[u,-.8,v],[u,.8,v]],[[u,v,-.8],[u,v,.8]]);}}
if(kind==='hyper'||kind==='layers'){const levels=kind==='layers'?[-.55,0,.55]:[0];for(const d of levels)for(let j=0;j<=16;j++){let k=-1+j/8;const f=(u,v)=>[u*.9,.42*(u*u-v*v)+d,v*.9];a.push(line(t=>f(k,t),-1,1),line(t=>f(t,k),-1,1));}}
if(kind==='nil'){for(let d=-1;d<=1;d++)for(let j=0;j<=12;j++){let k=-1+j/6;const f=(u,v)=>[u*.8,v*.7,.6*u*v+d*.35];a.push(line(t=>f(k,t),-1,1),line(t=>f(t,k),-1,1));}}
if(kind==='helix'){for(let j=0;j<18;j++){let p=j*TAU/18;a.push(line(t=>[.65*Math.cos(t*5+p),t,.65*Math.sin(t*5+p)],-1,1,70));}for(let j=0;j<=12;j++){let y=-1+j/6;a.push(line(t=>[.65*Math.cos(t),y,.65*Math.sin(t)],0,TAU,42));}}
if(kind==='sol'){for(let j=0;j<=16;j++){let y=-1+j/8;const x=.5*Math.exp(.7*y),z=.5*Math.exp(-.7*y);a.push([[-x,y,-z],[x,y,-z],[x,y,z],[-x,y,z],[-x,y,-z]]);}for(let j=0;j<=10;j++){let q=-1+j/5;for(let s of [-1,1]){a.push(line(y=>[q*.5*Math.exp(.7*y),y,s*.5*Math.exp(-.7*y)],-1,1));a.push(line(y=>[s*.5*Math.exp(.7*y),y,q*.5*Math.exp(-.7*y)],-1,1));}}}
modelCache[kind]=a;return a;}
function canvasContext(canvas){const r=canvas.getBoundingClientRect();if(!r.width||!r.height)return null;const d=Math.min(window.devicePixelRatio||1,2);const w=r.width,h=r.height;if(canvas.width!==Math.round(w*d)||canvas.height!==Math.round(h*d)){canvas.width=Math.round(w*d);canvas.height=Math.round(h*d);}const c=canvas.getContext('2d');if(!c)return null;c.setTransform(d,0,0,d,0,0);c.clearRect(0,0,w,h);return {c,w,h};}
function rotate(p,ry,rx){let [x,y,z]=p;let x1=x*Math.cos(ry)+z*Math.sin(ry),z1=-x*Math.sin(ry)+z*Math.cos(ry);return [x1,y*Math.cos(rx)-z1*Math.sin(rx),y*Math.sin(rx)+z1*Math.cos(rx)];}
function projected(p,w,h,scale,cy=.54){const z=7/(7-p[2]);return [w*.5+p[0]*scale*z,h*cy-p[1]*scale*z,z];}
function drawLines(c,paths,color,transform,project,alpha=.55){c.strokeStyle=color;c.lineWidth=.75;for(const path of paths){let depth=0;c.beginPath();path.forEach((p,i)=>{const q=transform(p),v=project(q);depth+=q[2];if(i===0)c.moveTo(v[0],v[1]);else c.lineTo(v[0],v[1]);});c.globalAlpha=Math.max(.13,Math.min(.85,alpha+depth/path.length*.13));c.stroke();}c.globalAlpha=1;}
function pair(){const cx=canvasContext($('#scene'));if(!cx)return;const {c,w,h}=cx,scale=Math.min(w/6.2,h/3.4)*state.zoom;const cam=p=>rotate(p,state.yaw,state.pitch);const proj=p=>projected(p,w,h,scale,.56);const angle=state.time*.16;
// A subtle reference plane gives rotation a stable spatial cue.
c.lineWidth=.5;c.strokeStyle='#567394';c.globalAlpha=.16;for(let i=-6;i<=6;i++){const a=proj(cam([-4,-1.28,i*.4])),b=proj(cam([4,-1.28,i*.4]));c.beginPath();c.moveTo(...a.slice(0,2));c.lineTo(...b.slice(0,2));c.stroke();}for(let i=-10;i<=10;i++){const a=proj(cam([i*.4,-1.28,-2.4])),b=proj(cam([i*.4,-1.28,2.4]));c.beginPath();c.moveTo(...a.slice(0,2));c.lineTo(...b.slice(0,2));c.stroke();}c.globalAlpha=1;
for(const [i,t] of [state.hex.low,state.hex.up].entries()){const off=i===0?-1.52:1.52;drawLines(c,model(t.kind),colors[i],p=>{const q=rotate(p,angle+(i?.35:-.35),.1);q[0]+=off;return cam(q);},proj,.55);}
const neck=[];for(let j=0;j<12;j++){let u=j*TAU/12;neck.push(line(x=>{const r=.12+.35*Math.pow(x/.78,2);return [x,r*Math.cos(u),r*Math.sin(u)];},-.78,.78,28));}for(let j=0;j<=12;j++){const x=-.78+j*1.56/12,r=.12+.35*Math.pow(x/.78,2);neck.push(line(u=>[x,r*Math.cos(u),r*Math.sin(u)],0,TAU,30));}drawLines(c,neck,'#adc9e6',cam,proj,.22);
for(let k=0;k<9;k++){const t=((state.time*.15+k/9)%1),x=-1.3+t*2.6,p=proj(cam([x,.04*Math.sin(t*TAU),0]));c.beginPath();c.fillStyle=t<.5?colors[0]:colors[1];c.globalAlpha=.65*Math.sin(Math.PI*t);c.arc(p[0],p[1],1.8,0,TAU);c.fill();}c.globalAlpha=1;
}
function atlas(){for(const b of $$('.geo-card')){const t=trigrams.find(t=>t.id===b.dataset.id),cx=canvasContext(b.querySelector('canvas'));if(!cx)continue;const {c,w,h}=cx;drawLines(c,model(t.kind),'#9fc8ff',p=>rotate(p,state.time*.12+.55,-.24),p=>projected(p,w,h,Math.min(w,h)*.4,.51),.56);}}
let netNodes=[];function network(){const cx=canvasContext($('#network'));if(!cx)return;const {c,w,h}=cx,R=Math.min(w*.32,h*.34),r=Math.min(31,w*.06);netNodes=hexagrams.map(hx=>{let li=trigrams.indexOf(hx.low),ui=trigrams.indexOf(hx.up),a=li*TAU/8-Math.PI/2,b=ui*TAU/8;return {h:hx,x:w/2+R*Math.cos(a)+r*Math.cos(b),y:h/2+R*Math.sin(a)+r*Math.sin(b)};});const nb=neighbors(state.hex);for(const p of netNodes)for(const target of neighbors(p.h)){if(target.id<p.h.id)continue;const q=netNodes[target.id-1],active=p.h===state.hex||target===state.hex;c.strokeStyle=active?'#91bdff':'#335375';c.globalAlpha=active?.88:.2;c.lineWidth=active?1.3:.7;c.beginPath();c.moveTo(p.x,p.y);c.lineTo(q.x,q.y);c.stroke();}c.globalAlpha=1;for(const p of netNodes){const active=p.h===state.hex,near=nb.includes(p.h);c.beginPath();c.fillStyle=active?'#b6d5ff':near?'#94badf':'#344e6b';c.arc(p.x,p.y,active?6:near?4:2.6,0,TAU);c.fill();if(active||near){c.font=(active?'16':'13')+'px sans-serif';c.textAlign='center';c.fillStyle=active?'#ebf4ff':'#a5bfdf';c.fillText(p.h.name,p.x,p.y-12);}}c.font='12px monospace';c.fillStyle='#718bad';c.textAlign='center';c.fillText('Q₆',w/2,h/2+4);}
$('#network').onclick=e=>{const r=$('#network').getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;const nearest=netNodes.map(n=>({...n,d:Math.hypot(n.x-x,n.y-y)})).sort((a,b)=>a.d-b.d)[0];if(nearest&&nearest.d<18)select(nearest.h);};
function draw(){if(state.view==='pair')pair();else if(state.view==='atlas')atlas();else network();}
let last=0;function animate(ts){requestAnimationFrame(animate);if(ts-last<33)return;const dt=Math.min((ts-last)/1000,.05);last=ts;if(document.hidden)return;if(state.running){state.time+=dt;if(state.view!=='network')draw();}}requestAnimationFrame(animate);
let pointer=null;const canvas=$('#scene');canvas.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse')canvas.setPointerCapture(e.pointerId);pointer={x:e.clientX,y:e.clientY};});canvas.addEventListener('pointermove',e=>{if(!pointer)return;const dx=e.clientX-pointer.x,dy=e.clientY-pointer.y;state.yaw=Math.max(-.7,Math.min(.7,state.yaw+dx*.007));state.pitch=Math.max(-.8,Math.min(.65,state.pitch+dy*.005));pointer={x:e.clientX,y:e.clientY};draw();});for(const type of ['pointerup','pointercancel','pointerleave'])canvas.addEventListener(type,()=>pointer=null);canvas.addEventListener('wheel',e=>{e.preventDefault();state.zoom=Math.max(.7,Math.min(1.3,state.zoom-e.deltaY*.001));$('#zoom').value=Math.round(state.zoom*100);draw();},{passive:false});
new ResizeObserver(()=>draw()).observe($('.visual-panel'));render();
